import java.util.Scanner;

public class Main {
    static long n, max_depth, current, base_value, min_res = Long.MAX_VALUE, limit;
    static long[] arr = new long[500000];

    static void dfs(long x, long s, long base, long depth) {
        if (s >= n) return;
        if (x == 0) {
            System.out.println(s);
            System.exit(0);
        }
        while (base > x) {
            base /= 10;
            depth--;
        }
        dfs(0, s + ((base * 10 + 1) - x) + depth + 1, base * 10 + 1, depth + 1);
        long q = x / base;
        dfs((base * 10 + 1) - x, s + depth + 1, base, depth);
        dfs(x - (base * q), s + (depth * q), base, depth);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        base_value = 1;
        limit = 1;
        while (base_value * 10 + 1 <= n) {
            base_value = base_value * 10 + 1;
            limit++;
        }
        for (int i = 0; i < n; i++)
            dfs(n, 0, base_value, limit);
        if (min_res == Long.MAX_VALUE) min_res = Math.min(n, 11 - n + 2);
        System.out.println(min_res);
        sc.close();
    }
}
